<?php
define('ABSPATH',__DIR__.'/');
require __DIR__.'/../src/RecoverySettings.php';
use OzekiResilience\M1\RecoverySettings;
function need($v,$m){if(!$v)throw new RuntimeException($m);}
$tables=['posts'=>[['ID'=>7,'post_type'=>'attachment','guid'=>'old-image']], 'postmeta'=>[['post_id'=>7,'meta_key'=>'_wp_attached_file','meta_value'=>'old.png']], 'terms'=>[], 'term_taxonomy'=>[]];
$incoming=$tables;$incoming['posts'][0]['guid']='different-image';
$prepared=['theme_mods_trial'=>['custom_logo'=>7,'prepared_only'=>'keep','background_color'=>'white'],'sidebars_widgets'=>['sidebar-1'=>['text-2','media_image-3'],'wp_inactive_widgets'=>[],'array_version'=>3],'widget_text'=>[2=>['title'=>'Prepared','text'=>'Static explanation']],'widget_media_image'=>[3=>['attachment_id'=>7,'url'=>'https://destination.invalid/old.png']],'tablepress_plugin_options'=>'{"tablepress_version":"prepared","custom_css":"prepared css","modules":{"prepared":true}}'];
$saved=['theme_mods_trial'=>['background_color'=>'black'],'theme_mods_other'=>['custom_logo'=>7],'sidebars_widgets'=>['sidebar-1'=>['text-99']],'tablepress_plugin_options'=>'{"tablepress_version":"source"}','tablepress_tables'=>'{"table_post":{"1":10},"last_id":1}'];
$before=$prepared;
$r=RecoverySettings::plan($saved,$prepared,$incoming,$tables,'trial');
need($prepared===$before,'Read-only planning');
need(!isset($r['options']['tablepress_plugin_options']),'Do not replace prepared global TablePress options');
need($r['options']['tablepress_tables']===$saved['tablepress_tables'],'Restore table registry');
need($r['options']['theme_mods_trial']['prepared_only']==='keep','Preserve non-target theme values');
need($r['options']['theme_mods_trial']['background_color']==='black','Apply recognized source value');
need(!isset($r['options']['theme_mods_trial']['custom_logo']),'ID collision cannot retain old logo');
need(!isset($r['options']['theme_mods_other']),'Do not change another theme');
need($r['options']['sidebars_widgets']['sidebar-1']===['text-2'],'Keep valid prepared widget; detach ambiguous image');
need(in_array('media_image-3',$r['options']['sidebars_widgets']['wp_inactive_widgets'],true),'Retain detached widget configuration');
need(!isset($r['options']['widget_text']),'Widget bodies never replaced');
$same=RecoverySettings::plan([],$prepared,$tables,$tables,'trial');
need($same['options']['sidebars_widgets']['sidebar-1']===['text-2','media_image-3'],'Stable media identity preserved');
need($same['options']['theme_mods_trial']['custom_logo']===7,'Stable logo preserved');
$saved['theme_mods_trial']['custom_logo']=0;
need(RecoverySettings::plan($saved,$prepared,$tables,$tables,'trial')['options']['theme_mods_trial']['custom_logo']===0,'Explicit empty is applied');
$tables['terms']=[['term_id'=>8,'slug'=>'prepared-menu']];$tables['term_taxonomy']=[['term_id'=>8,'taxonomy'=>'nav_menu']];
$prepared['theme_mods_trial']['nav_menu_locations']=['primary'=>8];
$prepared['widget_nav_menu']=[4=>['nav_menu'=>8]];$prepared['sidebars_widgets']['sidebar-1'][]='nav_menu-4';
$same=RecoverySettings::plan([],$prepared,$tables,$tables,'trial');
need($same['options']['theme_mods_trial']['nav_menu_locations']===['primary'=>8],'Prepared stable menu retained');
need(in_array('nav_menu-4',$same['options']['sidebars_widgets']['sidebar-1'],true),'Prepared stable menu widget retained');
$changed=$tables;$changed['terms'][0]['slug']='unrelated-menu';
$r=RecoverySettings::plan([],$prepared,$changed,$tables,'trial');
need($r['options']['theme_mods_trial']['nav_menu_locations']===[],'Menu ID collision detached');
need(!in_array('nav_menu-4',$r['options']['sidebars_widgets']['sidebar-1'],true),'Menu widget ID collision detached');
need(count(array_filter($r['report'],fn($item)=>$item['origin']==='destination'))>=2,'Destination adjustments separately identified');
$saved['theme_mods_trial']['nav_menu_locations']=[];
need(RecoverySettings::plan($saved,$prepared,$tables,$tables,'trial')['options']['theme_mods_trial']['nav_menu_locations']===[],'Explicit menu deletion retained');
$prepared['theme_mods_trial']['custom_css_post_id']=7;
$cssBefore=$tables;$cssBefore['posts'][0]=['ID'=>7,'post_type'=>'custom_css','post_content'=>'.prepared{color:red}','post_author'=>99,'post_parent'=>0];
$css=RecoverySettings::plan($saved,$prepared,$tables,$cssBefore,'trial');
need($css['local_posts'][0]['post_content']==='.prepared{color:red}'&&$css['local_posts'][0]['post_author']===99,'Prepared CSS body and author retained');
need($css['local_posts'][0]['ID']!==7&&$css['options']['theme_mods_trial']['custom_css_post_id']===$css['local_posts'][0]['ID'],'Prepared CSS ID collision remapped consistently');
echo "PASS prepared settings, source application, absent/empty, identity collision, widget placement and read-only planning\n";
